async fn wait_for_action_signal(
    connection: &zbus::Connection,
    id: u32,
    handler: impl ResponseHandler,
) -> zbus::Result<()> {
    // zbus 6 defers match-rule validation to `build`, so `build` is the only
    // fallible step of a rule; the failures it reports are returned unchanged.
    let action_signal_rule = MatchRule::builder()
        .msg_type(zbus::message::Type::Signal)
        .interface(xdg::NOTIFICATION_INTERFACE)
        .member("ActionInvoked")
        .build()?;

    let proxy = zbus::fdo::DBusProxy::new(connection).await?;
    proxy.add_match_rule(action_signal_rule).await?;

    let close_signal_rule = MatchRule::builder()
        .msg_type(zbus::message::Type::Signal)
        .interface(xdg::NOTIFICATION_INTERFACE)
        .member("NotificationClosed")
        .build()?;
    proxy.add_match_rule(close_signal_rule).await?;

    let mut stream = zbus::MessageStream::from(connection);
    signal_stream::wait_for_response(&mut stream, id, handler).await
