#[cfg(test)]
mod action_failure_tests {
    use super::*;
    use crate::response::NotificationResponse;

    const CHILD: &str = "NOTIFY_RUST_MISSING_BUS_CHILD";
    const MISSING_BUS: &str = "unix:path=/nonexistent/osprey-bus";
    const NAMED_TEST: &str =
        "xdg::zbus_rs::action_failure_tests::missing_session_bus_is_reported_not_dropped";

    /// The missing-bus contract. Run directly, this re-executes the binary with the address set for
    /// that process alone and fails unless the child's assertion passes, so the filtered test never
    /// passes vacuously.
    #[test]
    fn missing_session_bus_is_reported_not_dropped() {
        if std::env::var_os(CHILD).is_some() {
            assert_missing_bus_is_reported();
        } else {
            assert!(
                run_child(NAMED_TEST).success(),
                "the missing-session-bus assertion must pass in the child process"
            );
        }
    }

    fn assert_missing_bus_is_reported() {
        let result = zbus::block_on(handle_action(1, |_: &NotificationResponse| {}));
        assert!(
            result.is_err(),
            "a missing session bus must be reported, not dropped: {result:?}"
        );
    }

    /// Re-executes this binary with the missing-bus address, which only that process ever sees.
    fn run_child(test: &str) -> std::process::ExitStatus {
        std::process::Command::new(std::env::current_exe().expect("the test binary has a path"))
            .args(["--exact", test, "--nocapture"])
            .env(CHILD, "1")
            .env("DBUS_SESSION_BUS_ADDRESS", MISSING_BUS)
            .status()
            .expect("the test binary must start")
    }

    /// A libtest binary runs tests on several threads and `std::env::set_var` is unsound while they
    /// run, so only the child is configured; this process must never see the sentinel address.
    #[test]
    fn the_missing_bus_check_does_not_mutate_this_process_environment() {
        let (request, request_rx) = std::sync::mpsc::channel();
        let (observed_tx, observed) = std::sync::mpsc::channel();
        let reader = std::thread::spawn(move || {
            let _ = request_rx.recv();
            let _ = observed_tx.send(std::env::var("DBUS_SESSION_BUS_ADDRESS").ok());
        });
        let status = run_child(NAMED_TEST);
        let _ = request.send(());
        let seen = observed.recv().ok().flatten();
        reader.join().expect("the reader thread must not panic");
        assert!(
            status.success(),
            "the missing-session-bus check must pass in the child process"
        );
        assert_ne!(
            seen.as_deref(),
            Some(MISSING_BUS),
            "this process's environment was mutated: {seen:?}"
        );
    }
}

/// Turns a notification signal stream into exactly one typed response.
///
/// The stream carries `ActionInvoked` and `NotificationClosed` signals for every notification on the
/// session bus, so a caller has to keep draining it until its own id appears. The outcome of that
/// drain is a value: a response was delivered, or the listener failed. A stream error and a stream
/// that ends without a response are both failures and must not be reported as success.
pub(crate) mod signal_stream {
    use crate::response::{NotificationResponse, ResponseHandler};
    use futures_lite::{Stream, StreamExt};
    use std::sync::Arc;

    const ACTION_INVOKED: &str = "ActionInvoked";
    const NOTIFICATION_CLOSED: &str = "NotificationClosed";
    const DEFAULT_ACTION: &str = "default";

    /// The response carried by `message` for notification `id`, if it has one.
    fn response_for(message: &zbus::Message, id: u32) -> Option<NotificationResponse> {
        if message.header().message_type() != zbus::message::Type::Signal {
            return None;
        }
        match message.header().member().map(|member| member.as_str())? {
            ACTION_INVOKED => match message.body().deserialize::<(u32, String)>() {
                Ok((signal_id, action)) if signal_id == id => Some(action_response(action)),
                _ => None,
            },
            NOTIFICATION_CLOSED => match message.body().deserialize::<(u32, u32)>() {
                Ok((signal_id, reason)) if signal_id == id => {
                    Some(NotificationResponse::Closed(reason.into()))
                }
                _ => None,
            },
            _ => None,
        }
    }

    fn action_response(action: String) -> NotificationResponse {
        if action == DEFAULT_ACTION {
            NotificationResponse::Default
        } else {
            NotificationResponse::Action(action)
        }
    }

    /// Drains `stream` until notification `id` produces a response, then calls `handler` once.
    pub(crate) async fn wait_for_response<S>(
        stream: &mut S,
        id: u32,
        handler: impl ResponseHandler,
    ) -> zbus::Result<()>
    where
        S: Stream<Item = zbus::Result<zbus::Message>> + Unpin,
    {
        while let Some(item) = stream.next().await {
            if let Some(response) = response_for(&item?, id) {
                handler.call(&response);
                return Ok(());
            }
        }
        Err(zbus::Error::InputOutput(Arc::new(
            std::io::Error::from(std::io::ErrorKind::UnexpectedEof),
        )))
    }

    #[cfg(test)]
    mod tests {
        use super::*;
        use crate::response::CloseReason;
        use futures_lite::stream;
        use std::cell::RefCell;
        use zbus::export::serde::Serialize;

        const INTERFACE: &str = "org.freedesktop.Notifications";
        const PATH: &str = "/org/freedesktop/Notifications";

        fn signal(
            member: &str,
            body: impl Serialize + zbus::DynamicType,
        ) -> zbus::Result<zbus::Message> {
            zbus::Message::signal(PATH, INTERFACE, member).build(&body)
        }

        fn action_invoked(id: u32, action: &str) -> zbus::Message {
            signal(ACTION_INVOKED, (id, action)).expect("a signal message is well formed")
        }

        fn closed(id: u32, reason: u32) -> zbus::Message {
            signal(NOTIFICATION_CLOSED, (id, reason)).expect("a signal message is well formed")
        }

        fn other_member() -> zbus::Message {
            signal("SomethingElse", (1u32,)).expect("a signal message is well formed")
        }

        fn drain(items: Vec<zbus::Result<zbus::Message>>) -> (zbus::Result<()>, Option<NotificationResponse>) {
            let seen = RefCell::new(None);
            let mut items = stream::iter(items);
            let result = futures_lite::future::block_on(wait_for_response(&mut items, 7, |response: &NotificationResponse| {
                *seen.borrow_mut() = Some(response.clone());
            }));
            (result, seen.into_inner())
        }

        #[test]
        fn matching_action_invoked_calls_the_handler_once() {
            let (result, seen) = drain(vec![Ok(other_member()), Ok(action_invoked(7, "open"))]);
            assert!(result.is_ok(), "a delivered action is success: {result:?}");
            assert_eq!(seen, Some(NotificationResponse::Action("open".to_string())));
        }

        #[test]
        fn the_default_action_maps_to_the_default_response() {
            let (result, seen) = drain(vec![Ok(action_invoked(7, "default"))]);
            assert!(result.is_ok(), "a body click is success: {result:?}");
            assert_eq!(seen, Some(NotificationResponse::Default));
        }

        #[test]
        fn a_close_signal_maps_to_its_reason() {
            let (result, seen) = drain(vec![Ok(closed(7, 2))]);
            assert!(result.is_ok(), "a close is success: {result:?}");
            assert_eq!(seen, Some(NotificationResponse::Closed(CloseReason::Dismissed)));
        }

        #[test]
        fn another_notification_id_is_ignored_until_the_stream_ends() {
            let (result, seen) = drain(vec![Ok(action_invoked(8, "open")), Ok(closed(9, 1))]);
            assert!(seen.is_none(), "no other notification's response may be delivered");
            assert!(result.is_err(), "a stream that ends without our response is a failure: {result:?}");
        }

        #[test]
        fn a_stream_error_is_reported_not_dropped() {
            let (result, seen) = drain(vec![Ok(other_member()), Err(zbus::Error::Failure("bus dropped".into()))]);
            assert!(seen.is_none());
            assert!(result.is_err(), "a stream error must reach the caller: {result:?}");
        }

        #[test]
        fn a_stream_end_without_a_response_is_an_error() {
            let (result, seen) = drain(vec![Ok(other_member())]);
            assert!(seen.is_none());
            assert!(result.is_err(), "the connection ending is a failure: {result:?}");
        }
    }
}

